package com.easyperformance.program;
import com.easyperformance.program.ProgramTypes.ReviewerRole;import com.easyperformance.program.ProgramTypes.SubmissionStatus;import com.easyware.platform.UuidV7;import com.easyware.platform.audit.TenantAwareAuditEntity;import jakarta.persistence.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="program_review_submission",uniqueConstraints=@UniqueConstraint(name="uq_program_submission_assignment",columnNames={"tenant_id","participant_id","reviewer_assignment_key","review_round"}),indexes=@Index(name="ix_program_submission_tenant_participant",columnList="tenant_id, participant_id, status"))
public class ProgramReviewSubmission extends TenantAwareAuditEntity{
 @Id@Column(columnDefinition="uuid",nullable=false,updatable=false)private UUID id;@Column(name="program_id",columnDefinition="uuid",nullable=false)private UUID programId;@Column(name="participant_id",columnDefinition="uuid",nullable=false)private UUID participantId;@Column(name="reviewer_assignment_id",columnDefinition="uuid")private UUID reviewerAssignmentId;@Column(name="reviewer_assignment_key",nullable=false,length=80)private String reviewerAssignmentKey;@Column(name="actor_employee_id",columnDefinition="uuid",nullable=false)private UUID actorEmployeeId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private ReviewerRole role;@Column(name="review_round",nullable=false)private int round;@JdbcTypeCode(SqlTypes.JSON)@Column(name="answers_json",columnDefinition="jsonb",nullable=false)private String answersJson;@Column(name="overall_opinion",columnDefinition="text")private String overallOpinion;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private SubmissionStatus status;@Column(name="completed_at")private Instant completedAt;@Version@Column(name="row_version",nullable=false)private long rowVersion;
 @PrePersist void prePersist(){if(id==null)id=UuidV7.generate();if(status==null)status=SubmissionStatus.DRAFT;}public UUID getId(){return id;}public void setId(UUID v){id=v;}public UUID getProgramId(){return programId;}public void setProgramId(UUID v){programId=v;}public UUID getParticipantId(){return participantId;}public void setParticipantId(UUID v){participantId=v;}public UUID getReviewerAssignmentId(){return reviewerAssignmentId;}public void setReviewerAssignmentId(UUID v){reviewerAssignmentId=v;}public String getReviewerAssignmentKey(){return reviewerAssignmentKey;}public void setReviewerAssignmentKey(String v){reviewerAssignmentKey=v;}public UUID getActorEmployeeId(){return actorEmployeeId;}public void setActorEmployeeId(UUID v){actorEmployeeId=v;}public ReviewerRole getRole(){return role;}public void setRole(ReviewerRole v){role=v;}public int getRound(){return round;}public void setRound(int v){round=v;}public String getAnswersJson(){return answersJson;}public void setAnswersJson(String v){answersJson=v;}public String getOverallOpinion(){return overallOpinion;}public void setOverallOpinion(String v){overallOpinion=v;}public SubmissionStatus getStatus(){return status;}public void setStatus(SubmissionStatus v){status=v;}public Instant getCompletedAt(){return completedAt;}public void setCompletedAt(Instant v){completedAt=v;}public long getRowVersion(){return rowVersion;}
}
